-- SOURCE ONLY. Forward inert recovery; never restore an earlier Root row or historical admission.
-- One atomic transaction; stop on every error. Requires a real recovered-Edge readback and reviewed full capsule.
BEGIN;
DO $catalogo_recovery_preflight$
DECLARE
 pin constant text:='__FIX_COMPAT_RECOVERY_PARAMETERS_SHA256__';p jsonb;r mission_factory_owner.editor_release_readiness%ROWTYPE;
 cure jsonb;genjutsu jsonb;k text;n integer;source_sessions uuid[];para_sessions uuid[];
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR auth.uid()IS NOT NULL THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_OPERATOR';END IF;
 PERFORM set_config('search_path','',true);
 p:=nullif(current_setting('app.fix_eligibility_recovery_parameters',true),'')::jsonb;
 IF pin!~'^[0-9a-f]{64}$'OR p IS NULL OR public.combat_v2_sha256(p)<>pin
 OR p->>'schema_version'IS DISTINCT FROM 'fix-eligibility-recovery-parameters/1'THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_FULL_PARAMETERS_REQUIRED';END IF;
 FOR k IN SELECT unnest(ARRAY['root_sha256','root_row_sha256','db_sha256','configuration_sha256','release_admission_row_sha256','qualification_row_sha256','content_admission_rows_sha256'])LOOP
  IF coalesce(p#>>ARRAY['expected_current',k],'')!~'^[0-9a-f]{64}$'THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_CURRENT_PIN:%',k;END IF;
 END LOOP;
 FOR k IN SELECT unnest(ARRAY['root_sha256','db_sha256','configuration_sha256','code_identity_sha256','shared_manifest_sha256','private_functions_manifest_sha256','relations_manifest_sha256'])LOOP
  IF coalesce(p#>>ARRAY['expected_postflight',k],'')!~'^[0-9a-f]{64}$'THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_POST_PIN:%',k;END IF;
 END LOOP;
 IF(p#>>'{expected_current,root_bytes}')::integer NOT BETWEEN 1 AND 524288 OR(p#>>'{expected_postflight,root_bytes}')::integer NOT BETWEEN 1 AND 524288
 OR jsonb_array_length(p->'shared_functions')<>34 OR jsonb_array_length(p->'private_functions')<>66
 OR jsonb_array_length(p->'relations')<>12 OR jsonb_array_length(p->'triggers')<>10
 OR p#>>'{expected_current,party_runtime,release_sha256}'IS DISTINCT FROM p#>>'{expected_current,root_sha256}'
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_SCOPE';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0))THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_AVAILABILITY_BUSY';END IF;
 SELECT * INTO STRICT r FROM mission_factory_owner.editor_release_readiness WHERE singleton FOR UPDATE NOWAIT;
 IF r.revision_sha256 IS DISTINCT FROM p#>>'{expected_current,root_sha256}'OR r.observed_revision_sha256 IS DISTINCT FROM r.revision_sha256
 OR public.combat_v2_sha256(to_jsonb(r))IS DISTINCT FROM p#>>'{expected_current,root_row_sha256}'
 OR encode(extensions.digest(convert_to(r.canonical_preimage,'UTF8'),'sha256'),'hex')IS DISTINCT FROM r.revision_sha256
 OR octet_length(r.canonical_preimage)IS DISTINCT FROM(p#>>'{expected_current,root_bytes}')::integer
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_CURRENT_ROOT_DRIFT';END IF;
 IF EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE state='in_corso'AND closed_at IS NULL)
 OR EXISTS(SELECT 1 FROM public.master_v2_sessions WHERE stato NOT IN('chiusa','annullata')AND closed_at IS NULL)
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_QUIESCENCE_REQUIRED';END IF;
 IF EXISTS(SELECT 1 FROM combat_v2_genjutsu_internal.effects WHERE state IN('pending','active'))
 OR EXISTS(SELECT 1 FROM combat_v2_genjutsu_internal.sources x JOIN public.combat_v2_declarations d ON d.id=x.declaration_id WHERE d.state NOT IN('risolta','superflua','annullata'))
 OR EXISTS(SELECT 1 FROM combat_v2_genjutsu_internal.release_plans x JOIN public.combat_v2_declarations d ON d.id=x.declaration_id WHERE d.state NOT IN('risolta','superflua','annullata'))
 OR EXISTS(SELECT 1 FROM combat_panel_private.cure_preparations_v1 x JOIN public.combat_v2_declarations d ON d.id=x.declaration_id WHERE d.state NOT IN('risolta','superflua','annullata'))
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_NATIVE_SETTLEMENT_REQUIRED';END IF;
 IF EXISTS(SELECT 1 FROM public.combat_v2_sessions s WHERE(s.closed_at IS NULL OR s.state NOT IN('risolto','chiuso','annullato'))AND s.id IN(
  SELECT session_id FROM combat_v2_genjutsu_internal.staff_receipts UNION SELECT session_id FROM combat_v2_genjutsu_internal.sources
  UNION SELECT session_id FROM combat_v2_genjutsu_internal.effects UNION SELECT(source->>'session_id')::uuid FROM combat_v2_genjutsu_internal.release_plans
  UNION SELECT session_id FROM combat_panel_private.cure_staff_profiles_v1 UNION SELECT session_id FROM combat_panel_private.cure_preparations_v1))
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_NATIVE_CLOSE_OWN_PROOFS_REQUIRED';END IF;
 -- Provenienza durevole delle sole nuove fonti: non richiama scope attivi/in_corso.
 SELECT coalesce(array_agg(sid ORDER BY sid),'{}'::uuid[])INTO source_sessions FROM(
  SELECT session_id AS sid FROM combat_panel_private.cure_preparations_v1
  UNION SELECT session_id FROM combat_panel_private.cure_staff_profiles_v1
  UNION SELECT session_id FROM combat_v2_genjutsu_internal.staff_receipts
  UNION SELECT session_id FROM combat_v2_genjutsu_internal.sources
  UNION SELECT session_id FROM combat_v2_genjutsu_internal.effects
  UNION SELECT a.session_id FROM combat_v2_genjutsu_internal.preparations x JOIN public.combat_v2_actors a ON a.id=x.actor_id
  UNION SELECT(source->>'session_id')::uuid FROM combat_v2_genjutsu_internal.release_plans)s;
 SELECT coalesce(array_agg(sid ORDER BY sid),'{}'::uuid[])INTO para_sessions FROM(
  SELECT session_id AS sid FROM combat_v2_genjutsu_internal.staff_receipts
  UNION SELECT session_id FROM combat_v2_genjutsu_internal.sources
  UNION SELECT session_id FROM combat_v2_genjutsu_internal.effects
  UNION SELECT a.session_id FROM combat_v2_genjutsu_internal.preparations x JOIN public.combat_v2_actors a ON a.id=x.actor_id
  UNION SELECT(source->>'session_id')::uuid FROM combat_v2_genjutsu_internal.release_plans)s;
 IF(SELECT count(*)FROM public.combat_v2_sessions WHERE id=ANY(source_sessions))<>cardinality(source_sessions)
 OR EXISTS(SELECT 1 FROM public.combat_v2_sessions s WHERE s.id=ANY(source_sessions)AND NOT EXISTS(
  SELECT 1 FROM public.locations l WHERE l.id=s.location_id AND l.id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND l.is_test
   AND s.user_test_context_id IS NULL AND s.closed_at IS NOT NULL AND s.state IN('risolto','chiuso','annullato')
   AND public.combat_v2_values_written(s.id)IS FALSE
   AND EXISTS(SELECT 1 FROM public.combat_v2_actors a WHERE a.session_id=s.id AND a.actor_kind='pg')
   AND NOT EXISTS(SELECT 1 FROM public.combat_v2_actors a WHERE a.session_id=s.id AND a.actor_kind='pg'AND(a.companion_id IS NOT NULL
    OR a.character_id IS NULL OR a.character_id NOT IN('2a877f02-4993-4e65-9172-7d29f08c5b86'::uuid,'6bceee99-974f-426b-8d92-38b43b4a4267'::uuid)))
   AND(NOT(s.id=ANY(para_sessions))OR((SELECT count(*)FROM public.combat_v2_actors a WHERE a.session_id=s.id)=2
    AND(SELECT count(DISTINCT a.character_id)FROM public.combat_v2_actors a WHERE a.session_id=s.id)=2
    AND NOT EXISTS(SELECT 1 FROM public.combat_v2_actors a WHERE a.session_id=s.id AND a.actor_kind<>'pg')))
   AND((s.source_kind='ordinary'AND s.master_session_id IS NULL
     AND EXISTS(SELECT 1 FROM combat_consumer_private.activities c WHERE c.session_id=s.id AND c.user_test_context_id IS NULL
      AND c.policy_id='staff_test_no_persistent_resources_v1')
     AND NOT EXISTS(SELECT 1 FROM public.combat_v2_actors a WHERE a.session_id=s.id AND NOT EXISTS(
      SELECT 1 FROM combat_consumer_private.members cm WHERE cm.session_id=s.id AND cm.actor_id=a.id AND cm.character_id=a.character_id)))
    OR(s.source_kind='master'AND EXISTS(SELECT 1 FROM public.master_v2_sessions m
      JOIN combat_panel_private.master_panel_sessions mp ON mp.master_session_id=m.id
      WHERE m.id=s.master_session_id AND m.owner_kind='human'AND m.tipo='duello'AND m.mission_id IS NULL AND m.quest_kind IS NULL
       AND m.closed_at IS NOT NULL AND m.stato IN('chiusa','annullata')AND mp.policy_id='staff_test_no_persistent_resources_v1')))))
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_DURABLE_STAFF_SOURCE_SCOPE_REQUIRED';END IF;
 -- Appartenenze storiche escluse anche se gia terminali/pubblicate; nessun drain di questi domini.
 IF EXISTS(SELECT 1 FROM public.combat_v2_sessions s WHERE s.id=ANY(source_sessions)AND(
  EXISTS(SELECT 1 FROM public.mission_run_state x WHERE x.master_session_id=s.master_session_id)
  OR EXISTS(SELECT 1 FROM combat_consumer_private.narrative_authorities x WHERE x.master_session_id=s.master_session_id)
  OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources x WHERE x.session_id=s.master_session_id)
  OR EXISTS(SELECT 1 FROM mission_narrative_internal.scene_runtime_v1 x WHERE x.master_session_id=s.master_session_id)
  OR EXISTS(SELECT 1 FROM mission_generic_owner.unified_batches x WHERE x.encounter_id=s.id OR x.master_session_id=s.master_session_id)
  OR EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_windows_v1 x WHERE x.master_session_id=s.master_session_id OR x.encounter_id=s.id)
  OR EXISTS(SELECT 1 FROM mission_generic_owner.regia_human_admissions_v1 x WHERE x.encounter_id=s.id)
  OR EXISTS(SELECT 1 FROM exam_regia_private.bindings x WHERE x.combat_session_id=s.id OR x.master_session_id=s.master_session_id)
  OR EXISTS(SELECT 1 FROM exam_human_private.native_bindings x WHERE x.master_session_id=s.master_session_id)))
 OR EXISTS(SELECT 1 FROM mission_generic_owner.unified_round_windows x JOIN public.combat_v2_rounds r ON r.id=x.round_id
  WHERE r.session_id=ANY(source_sessions))
 OR EXISTS(SELECT 1 FROM exam_human_private.round_publication_windows_v1 x JOIN public.combat_v2_rounds r
  ON r.id=x.next_round_id OR r.id=x.source_round_id WHERE r.session_id=ANY(source_sessions))
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_HISTORICAL_MISSION_REGIA_QUEST_EXAM_SCOPE_FORBIDDEN';END IF;
 -- Le fonti restano quelle sigillate dal server e gli eventuali ledger solo simulati.
 IF EXISTS(SELECT 1 FROM combat_panel_private.cure_preparations_v1 x WHERE x.session_id=ANY(source_sessions)
   AND(x.source->>'scope_kind'IS DISTINCT FROM 'simulation'OR x.source_sha256 IS DISTINCT FROM public.combat_v2_sha256(x.source)))
 OR EXISTS(SELECT 1 FROM combat_panel_private.cure_ledger_v1 x WHERE x.session_id=ANY(source_sessions)
   AND(NOT x.is_simulated OR x.applied_real_gain<>0 OR x.facts->'values_written'IS DISTINCT FROM 'false'::jsonb))
 OR EXISTS(SELECT 1 FROM combat_v2_genjutsu_internal.sources x WHERE x.session_id=ANY(source_sessions)
   AND combat_v2_genjutsu_internal.source_valid(x.declaration_id)IS NOT TRUE)
 OR EXISTS(SELECT 1 FROM combat_v2_genjutsu_internal.staff_receipts x WHERE x.session_id=ANY(source_sessions)
   AND(x.receipt_sha256 IS DISTINCT FROM public.combat_v2_sha256(x.receipt)OR x.receipt->'values_written'IS DISTINCT FROM 'false'::jsonb))
 OR EXISTS(SELECT 1 FROM public.combat_v2_round_reports x JOIN public.combat_v2_rounds r ON r.id=x.round_id
   WHERE r.session_id=ANY(source_sessions)AND x.values_written)
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_NON_SIMULATED_OR_INVALID_FROZEN_SOURCE';END IF;
 IF EXISTS(SELECT 1 FROM public.combat_v2_round_reports x JOIN public.combat_v2_rounds r ON r.id=x.round_id
   WHERE r.session_id=ANY(source_sessions)AND x.narration_state='attesa')
 OR EXISTS(SELECT 1 FROM combat_consumer_private.narrative_claims x WHERE x.session_id=ANY(source_sessions)AND x.state='claimed')
 OR EXISTS(SELECT 1 FROM combat_consumer_private.scene_attempts_v2 x JOIN public.combat_v2_rounds r ON r.id=x.round_id
   WHERE r.session_id=ANY(source_sessions)AND x.state NOT IN('published','failed'))
 OR EXISTS(SELECT 1 FROM combat_consumer_private.dispatch_authorizations x JOIN public.combat_v2_rounds r ON r.id=x.round_id
   WHERE r.session_id=ANY(source_sessions)AND x.state='prepared')
 OR EXISTS(SELECT 1 FROM combat_consumer_private.publish_authorizations x JOIN combat_consumer_private.narrative_claims c ON c.request_key=x.request_key
   WHERE c.session_id=ANY(source_sessions)AND x.state='prepared')
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_OWN_NARRATIVE_OR_DISPATCH_PENDING';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='clan_innata_private.eligibility_release_assert()'::regprocedure
  AND md5(prosrc)='250e7511806ab0fe07b6bf24b2a1770a'AND proowner='postgres'::regrole AND prosecdef)
 OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='clan_innata_private.catalogo_eligibility_release_v1()'::regprocedure
  AND md5(prosrc)='bde885b7cec62845d6e21d8116a07dbd'AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=""']AND proacl='{postgres=X/postgres}'::aclitem[])
 OR r.canonical_preimage::jsonb#>>'{db_core,catalogo_eligibility_compat,normalized_source_identity_sha256}'IS DISTINCT FROM '17fd985dfe72c4c6ad3638c01ad019a1f3deb1c21f587a6a0e98c39458e6550f'
 OR r.canonical_preimage::jsonb#>'{db_core,catalogo_eligibility_compat}'IS DISTINCT FROM r.canonical_preimage::jsonb#>'{config,catalogo_eligibility_compat}'
 THEN RAISE EXCEPTION 'FIX_COMPAT_RECOVERY_CURRENT_REPAIR_DRIFT';END IF;
 SELECT to_jsonb(g)INTO STRICT cure FROM combat_panel_private.cure_gate_v1 g WHERE singleton FOR UPDATE;
 SELECT to_jsonb(g)INTO STRICT genjutsu FROM combat_v2_genjutsu_internal.gate g WHERE singleton FOR UPDATE;
 IF cure IS DISTINCT FROM p#>'{expected_current,cure_gate}'OR genjutsu IS DISTINCT FROM p#>'{expected_current,genjutsu_gate}'
 OR cure->>'contract_version'IS DISTINCT FROM 'palmo-curativo/1'OR cure->'public_enabled'IS DISTINCT FROM 'false'::jsonb
 OR genjutsu->'version'IS DISTINCT FROM '1'::jsonb OR genjutsu->'public_enabled'IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_GATE_CAS';END IF;
 UPDATE combat_panel_private.cure_gate_v1 SET staff_enabled=false,public_enabled=false WHERE singleton;
 GET DIAGNOSTICS n=ROW_COUNT;IF n<>1 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_CURE_GATE_COUNT';END IF;
 UPDATE combat_v2_genjutsu_internal.gate SET enabled=false,staff_enabled=false,public_enabled=false WHERE singleton;
 GET DIAGNOSTICS n=ROW_COUNT;IF n<>1 THEN RAISE EXCEPTION 'CATALOGO_RECOVERY_GENJUTSU_GATE_COUNT';END IF;
END $catalogo_recovery_preflight$;

-- Exactly34 inverse hooks, all preimages checked before the first replacement.
-- Exact shared-function delta. Integrate only with the reviewed family/Root/Edge plan.
DO $cc_shared$
DECLARE patches jsonb:=$cc_hunks$[{"signature":"public.combat_v2_action_declare(uuid,uuid,jsonb,text,uuid)","before_sha256":"a6031c7e390241dd7fad8e81be90ae8f3dc57e2283e742c19047d046c9e93f6d","after_sha256":"75d97156e8cf34775d830d9cef7aa18ab421e752b423abc9eb4a64860568e72b","after_source_md5":"0812d256aa3dea03be7e70685526a853","hunks":[{"before":"AS $function$\ndeclare v_uid uuid:=exam_regia_private.current_principal(); v_service boolean:=false; v_service_actor uuid; v_r public.combat_v2_rounds%rowtype; v_a public.combat_v2_actors%rowtype; v_t public.combat_v2_actors%rowtype;\n  fireball clan_uchiha_private.fireball_preparations%ROWTYPE; clone_meta jsonb; escape_meta jsonb; aburame_meta jsonb;  multiplication_aim_valid boolean; multiplication_meta jsonb; v_i jsonb; v_kind text; v_target uuid; v_source text; v_ability uuid; v_meta jsonb; v_cost int:=0; v_base int:=10;\n  cure_meta jsonb;\n    genjutsu_release_meta jsonb;\n  v_nara_native boolean := false;\n  v_nara_public_enabled boolean;\n  v_nara_public_activated_at timestamptz;\n","after":"AS $function$\ndeclare v_uid uuid:=exam_regia_private.current_principal(); v_service boolean:=false; v_service_actor uuid; v_r public.combat_v2_rounds%rowtype; v_a public.combat_v2_actors%rowtype; v_t public.combat_v2_actors%rowtype;\n  fireball clan_uchiha_private.fireball_preparations%ROWTYPE; clone_meta jsonb; escape_meta jsonb; aburame_meta jsonb;  multiplication_aim_valid boolean; multiplication_meta jsonb; v_i jsonb; v_kind text; v_target uuid; v_source text; v_ability uuid; v_meta jsonb; v_cost int:=0; v_base int:=10;\n  v_nara_native boolean := false;\n  v_nara_public_enabled boolean;\n  v_nara_public_activated_at timestamptz;\n","occurrences":1},{"before":"  if not v_service and exam_regia_private.actor_principal(v_a.id,v_a.controller_user)<>v_uid then perform public.combat_v2_fail('attore_non_controllato','Non controlli questo attore.',403,p_request_key,'{}'); end if;\n  if v_a.state<>'attivo' then perform public.combat_